SELECT  FROM cut_plan_revision
WHERE tenant_id = #{query.tenantId} AND task_id = #{query.taskId}
  AND current_marker = 1 AND deleted = b'0'
AND id = #{query.planRevisionId}

SELECT  FROM cut_plan_revision
WHERE tenant_id = #{query.tenantId} AND task_id = #{query.taskId}
  AND origin_code = 'LEGACY_FORWARD' AND current_marker IS NULL AND deleted = b'0'
AND id = #{query.planRevisionId}
ORDER BY revision_no ASC, legacy_plan_id ASC, id ASC
LIMIT 2

SELECT  FROM cut_plan_revision
WHERE tenant_id = #{query.tenantId} AND task_id = #{query.taskId}
  AND current_marker = 1 AND deleted = b'0'
AND id = #{query.planRevisionId}
FOR UPDATE

mapper.update:
UPDATE cut_plan_revision
SET version = #{query.newVersion}, updater = #{query.updater}, update_time = #{query.updateTime}
WHERE tenant_id = #{query.tenantId} AND id = #{query.planRevisionId}
  AND status_code = 'SUBMITTED' AND current_marker = 1
  AND approval_instance_id IS NOT NULL AND version = #{query.expectedVersion} AND deleted = b'0'

UPDATE cut_plan_revision
SET current_marker = NULL, version = #{query.newVersion},
    updater = #{query.updater}, update_time = #{query.updateTime}
WHERE tenant_id = #{query.tenantId} AND id = #{query.planRevisionId}
  AND status_code = 'SUBMITTED' AND current_marker = 1
  AND version = #{query.expectedVersion} AND deleted = b'0'
